1449	fn residual_rows<const L: usize, const R: usize>(
1450	    ctx: &mut WideContext<L>,
1451	    ctx_q: &mut WideContext<R>,
1452	    ctx64: &mut WideContext<4>,
1453	    ctx16: &mut WideContext<16>,
1454	    sum: &mut ExactWideSum,
1455	    p: u32,
1456	    structure: &Structure,
1457	    k_q: &[Wide<R>],
1458	    ledger: &RetainedLedger,
1459	    free: &[usize],
1460	    u: &[Wide<L>],
1461	    tracker: &mut BoundedExtremeTracker,
1462	) -> Result<Vec<(bool, f64, Wide<L>)>, AttemptStop>
1463	where
1464	    Wide<L>: SupportedWidth,
1465	    Wide<R>: SupportedWidth,
1466	{
1467	    let mut rows = Vec::with_capacity(free.len());
1468	    for &i in free {
1469	        // r_i = f_i − Σ_j K^q_ij·u_j (exact); d_i = |f_i| + Σ_j |K^q_ij·u_j|.
1470	        let mut r = ExactWideSum::new();
1471	        let mut d = ExactWideSum::new();
1472	        ledger.add_to(i, &mut r, false)?;
1473	        if let Some(net) = ledger.net(i) {
1474	            if !net.is_zero() {
1475	                d.add_integer(false, &net.magnitude, net.exponent)?;
1476	            }
