1478	        let mut count = 0u64;
1479	        for index in structure.pattern.row_range(i) {
1480	            let j = structure.pattern.column(index);
1481	            let kij = &k_q[index];
1482	            let uj = u[j].widen::<R>();
1483	            if kij.is_zero() || uj.is_zero() {
