1513	/// num/den against another exact ratio (dens positive), decided exactly.
1514	fn cmp_ratio(
1515	    a: &(ExactWideSum, ExactWideSum),
1516	    b: &(ExactWideSum, ExactWideSum),
1517	) -> Result<CmpOrdering, AttemptStop> {
1518	    let mut t = ExactWideSum::new();
1519	    let mut db = b.1.clone();
1520	    t.add_product_of(&a.0, &mut db, false)?;
1521	    let mut da = a.1.clone();
1522	    t.add_product_of(&b.0, &mut da, true)?;
