1529	/// The gate's bounded row test (R7 §4.1.4 step 3), exactly: with
1530	/// num = |r|·(2^p − m) and den = 64·m·d^b, whether num ≤ den, and the pair.
1531	pub(crate) fn bounded_row(
1532	    r: ExactWideSum,
1533	    d: &ExactWideSum,
1534	    m: u64,
1535	    p: u32,
1536	    sum: &mut ExactWideSum,
1537	) -> Result<(bool, GateRatio), AttemptStop> {
1538	    let mut absolute = r;
1539	    absolute.make_absolute();
1540	    let mut num = ExactWideSum::new();
1541	    num.add_scaled(&absolute, false, 1, i64::from(p))?;
1542	    num.add_scaled(&absolute, true, m, 0)?;
1543	    let mut den = ExactWideSum::new();
1544	    den.add_scaled(d, false, 64 * m, 0)?;
1545	    sum.clear();
1546	    sum.add_scaled(&den, false, 1, 0)?;
1547	    sum.add_scaled(&num, true, 1, 0)?;
1548	    Ok((sum.signum() >= 0, (num, den)))
1549	}
